select t.slug, ss.code, left(ss.title, 50) as title from syllabus_statements ss join topics t on t.id = ss.topic_id join subject_levels sl on sl.id=t.subject_level_id join subjects s on s.id=sl.subject_id where s.name ilike '%physics%' and sl.level::text='OL' and t.slug in ('earth-space','magnetism','nuclear','thermal','waves-sound') order by t.slug, ss.code;
select t.slug, (select count(*) from questions q join quizzes z on z.id=q.quiz_id where z.topic_id=t.id and q.difficulty='exam' and q.statement_id is not null) as linked, (select count(*) from flashcards f join flashcard_sets fs on fs.id=f.set_id where fs.topic_id=t.id) as fc, (select length(sm.content) from study_materials sm where sm.topic_id=t.id and sm.material_type='notes' order by length(sm.content) desc limit 1) as notes from topics t where t.slug in ('earth-space','magnetism','nuclear','thermal','waves-sound') order by t.slug;
